import { Component } from '@angular/core';
import { HeaderComponent } from './header/header.component';
import { FooterComponent } from './footer/footer.component';
import { MainLoaderComponent } from './loaders/main-loader.component';
import { UiLoaderComponent } from './loaders/ui-loader.component';
import { BackendLoaderComponent } from './loaders/backend-loader.component';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    HeaderComponent,
    FooterComponent,
    MainLoaderComponent,
    UiLoaderComponent,
    BackendLoaderComponent,
  ],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css'],
})
export class AppComponent {
  title = 'shell-app';
}
<div class="shell-layout">
  <app-header></app-header>

  <main class="content-area">
    <section class="main-section">
      <app-main-loader></app-main-loader>
    </section>

    <section class="panels-section">
      <div class="left-panel">
        <app-ui-loader></app-ui-loader>
      </div>
      <div class="right-panel">
        <app-backend-loader></app-backend-loader>
      </div>
    </section>
  </main>

  <app-footer></app-footer>
</div>
